import './DataTable.css';

export type Row = Record<string, string | number>;

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const PLACEHOLDER_ROW_COUNT = 5;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns =
    rows.length > 0 ? Object.keys(rows[0]) : [];

  const placeholderColumns = loading && columns.length === 0 ? ['col1', 'col2', 'col3'] : columns;

  return (
    <table role="table" className="data-table">
      <thead>
        <tr role="row">
          {placeholderColumns.map((col) => (
            <th key={col} role="columnheader" className="data-table-header-cell">
              {loading ? '' : col}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {loading
          ? Array.from({ length: PLACEHOLDER_ROW_COUNT }, (_, rowIndex) => (
              <tr key={rowIndex} role="row" className="data-table-row">
                {placeholderColumns.map((col) => (
                  <td key={col} role="cell" className="data-table-shimmer-cell">
                    <div className="data-table-shimmer-bar" />
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row, rowIndex) => (
              <tr key={rowIndex} role="row" className="data-table-row">
                {columns.map((col) => (
                  <td key={col} role="cell" className="data-table-cell">
                    {row[col]}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}
